// Unit tests for the search query language (SCN-008, SCN-009).
const test = require('node:test');
const assert = require('node:assert');
const { compile } = require('../lib/search');

const B = [
  { title: 'Rome travel guide', url: 'http://x.com/rome', desc: 'ancient city', note: 'plan trip', tags: ['article', 'travel'] },
  { title: 'Rome history book', url: 'http://y.com', desc: 'empire', note: '', tags: ['book'] },
  { title: 'Paris cafes', url: 'http://z.com', desc: 'coffee', note: 'rome mentioned', tags: ['article'] },
];
const run = (q) => B.map((b, i) => (compile(q)(b) ? i : null)).filter(x => x !== null);

test('plain word is case-insensitive across title/url/desc/note', () => {
  assert.deepStrictEqual(run('ROME'), [0, 1, 2]);
  assert.deepStrictEqual(run('empire'), [1]);
});
test('exact phrase in quotes', () => {
  assert.deepStrictEqual(run('"ancient city"'), [0]);
});
test('tag term matches exact tag only', () => {
  assert.deepStrictEqual(run('#book'), [1]);
});
test('grouped tags with implicit AND on a bare word', () => {
  assert.deepStrictEqual(run('rome (#article OR #book)'), [0, 1, 2]);
});
test('NOT excludes', () => {
  assert.deepStrictEqual(run('rome NOT #article'), [1]);
});
test('operators are case-insensitive when bare', () => {
  assert.deepStrictEqual(run('rome (#article or #book)'), run('rome (#article OR #book)'));
  assert.deepStrictEqual(run('rome not #article'), run('rome NOT #article'));
});
test('a quoted operator word is a literal term, not an operator', () => {
  // "or" is treated as literal text: matches "hist(or)y" in bookmark 1, not as the OR operator.
  assert.deepStrictEqual(run('"or"'), [1]);
  assert.deepStrictEqual(run('"coffee"'), [2]);
});
test('empty query matches everything', () => {
  assert.deepStrictEqual(run(''), [0, 1, 2]);
});
test('unreadable query throws', () => {
  assert.throws(() => compile('rome (#article'));
  assert.throws(() => compile('"unterminated'));
});
// Import/export round-trip in standard bookmark HTML (SCN-021).
const test = require('node:test');
const assert = require('node:assert');
const { generate, parse } = require('../lib/bookmarksHtml');

test('parse preserves title, tags, date and note', () => {
  const html = `<!DOCTYPE NETSCAPE-Bookmark-file-1><DL><p>
    <DT><A HREF="https://a.example/p" ADD_DATE="1600000000" TAGS="reading,history">Alpha</A>
    <DD>Note about alpha
    <DT><A HREF="https://b.example/" ADD_DATE="1700000000">Beta</A>
  </DL><p>`;
  const items = parse(html);
  assert.strictEqual(items.length, 2);
  assert.strictEqual(items[0].title, 'Alpha');
  assert.deepStrictEqual(items[0].tags, ['reading', 'history']);
  assert.strictEqual(items[0].createdAt, 1600000000 * 1000);
  assert.strictEqual(items[0].note, 'Note about alpha');
  assert.deepStrictEqual(items[1].tags, []);
});

test('non-http links are ignored on import', () => {
  const items = parse('<A HREF="javascript:alert(1)">x</A><A HREF="https://ok.example">ok</A>');
  assert.strictEqual(items.length, 1);
  assert.strictEqual(items[0].url, 'https://ok.example');
});

test('generate then parse round-trips core fields', () => {
  const bm = [{ url: 'https://c.example/x', title: 'Cee', tags: ['t1', 't2'], note: 'hi', createdAt: 1650000000 * 1000 }];
  const round = parse(generate(bm));
  assert.strictEqual(round[0].url, 'https://c.example/x');
  assert.strictEqual(round[0].title, 'Cee');
  assert.deepStrictEqual(round[0].tags, ['t1', 't2']);
  assert.strictEqual(round[0].note, 'hi');
  assert.strictEqual(round[0].createdAt, 1650000000 * 1000);
});

test('export escapes HTML-special characters', () => {
  const out = generate([{ url: 'https://x/?a=1&b=2', title: 'A & <b>', tags: [], note: '', createdAt: Date.now() }]);
  assert.match(out, /A &amp; &lt;b&gt;/);
  assert.match(out, /a=1&amp;b=2/);
});
// Metadata extraction (SCN-001, SCN-002, SCN-015) with a stubbed fetch.
const test = require('node:test');
const assert = require('node:assert');
const { fetchMetadata } = require('../lib/metadata');

function fakeResponse(html, contentType = 'text/html', bytes = null) {
  return {
    headers: { get: (k) => (k.toLowerCase() === 'content-type' ? contentType : null) },
    text: async () => html,
    arrayBuffer: async () => bytes || Buffer.from(''),
  };
}

test('extracts og title/description/image and favicon', async () => {
  const html = `<html><head>
    <title>Fallback</title>
    <meta property="og:title" content="OG Title">
    <meta property="og:description" content="OG Desc">
    <meta property="og:image" content="/img/preview.png">
    <link rel="icon" href="/favicon-32.png">
  </head><body></body></html>`;
  const m = await fetchMetadata('https://site.example/page', { fetchImpl: async () => fakeResponse(html) });
  assert.strictEqual(m.ok, true);
  assert.strictEqual(m.title, 'OG Title');
  assert.strictEqual(m.desc, 'OG Desc');
  assert.strictEqual(m.image, 'https://site.example/img/preview.png');
  assert.strictEqual(m.favicon, 'https://site.example/favicon-32.png');
  assert.strictEqual(m.isPdf, false);
});

test('falls back to <title> and /favicon.ico', async () => {
  const html = `<html><head><title>Just Title</title></head><body></body></html>`;
  const m = await fetchMetadata('https://www.site.example/x', { fetchImpl: async () => fakeResponse(html) });
  assert.strictEqual(m.title, 'Just Title');
  assert.strictEqual(m.favicon, 'https://www.site.example/favicon.ico');
  assert.strictEqual(m.image, null);
});

test('detects a PDF by content-type', async () => {
  const m = await fetchMetadata('https://site.example/report', { fetchImpl: async () => fakeResponse('', 'application/pdf') });
  assert.strictEqual(m.isPdf, true);
  assert.strictEqual(m.ok, true);
});

test('failed lookup returns ok:false but keeps site/favicon (SCN-002)', async () => {
  const m = await fetchMetadata('https://down.example/x', { fetchImpl: async () => { throw new Error('boom'); } });
  assert.strictEqual(m.ok, false);
  assert.strictEqual(m.site, 'down.example');
  assert.strictEqual(m.favicon, 'https://down.example/favicon.ico');
});
